@startuml

class Airline {
  + Name : string
}

class Employee {
  + Name : string
  + DateOfEmployment : date
}

class FlightAttendant extends Employee {
  + IsChiefStewardess : boolean
}

class Pilot extends Employee {
  + License : string
}

class Airplane {
  + Name : string
  + Type : string
  + YearOfManufacture : int
  + NextInspectionDate : date
}

class PassengerPlane extends Airplane {
  + NumberOfSeats : int
}

class SeatCategory {
  + Designation : string
  + OffersEntertainment : boolean
  + SeatCount : int
}

class Flight {
  + FlightNumber : string
  + Date : date
}

class Passenger {
  + Name : string
  + PassportNumber : string
}

class Ticket {
  + TicketNumber : string
  + Price : float
  + UpgradeDesired : boolean
}

class Airport {
  + Name : string
  + Address : string
  + RunwayNumber : int
}

Airline "0..1" -- "0..*" Employee
Airline "0..1" o-- "0..*" Airplane
Airplane "0..1" -- "0..1" Airport : home airport
Airplane "1" -- "0..*" Flight
Flight "1" -- "1" Airport : departure airport
Flight "1" -- "1" Airport : destination airport
Flight "0..*" -- "0..*" FlightAttendant
Flight "1" -- "1 Captain" Pilot
Flight "1" -- "1..2 Co-pilot" Pilot
Flight "0..*" -- "0..*" Passenger
Flight "1" -- "0..*" Ticket
PassengerPlane "1" *-- "0..*" SeatCategory
SeatCategory "1" -- "0..*" Ticket
Passenger "1" -- "0..*" Ticket

@enduml

